                </Text>
                <Text
                  numberOfLines={1}
                  style={{ color: theme.colors.secondaryText, fontSize: 12 }}
                >
                  {p.notes_root}
                </Text>
              </View>
            </Pressable>
          );
        })}
        <Field
          label="New working folder"
          value={newFolderName}
          onChangeText={setNewFolderName}
          placeholder="e.g. Journal"

