    DispatchQueue.main.async {
      NativeEdgeMenuController.shared.open(animated: true)
    }
  }

  @objc func closeMenu() {
    DispatchQueue.main.async {
      NativeEdgeMenuController.shared.close(animated: true)
    }
  }
}

